const cached=new Map;const caching=(req,res,next)=>{const realPath=req.path;const cachedResponse=cached.get(req.originalUrl||req.url);if(cachedResponse&&cachedResponse.ttl>Date.now()){return res.status(cachedResponse.status).json(JSON.parse(cachedResponse.body))}else{const expressBody=res.send.bind(res);res.send=body=>{if(!req.ext.constants.NOT_CACHED_PATH.includes(realPath)){cached.set(req.originalUrl||req.url,{body,status:res.statusCode,ttl:Date.now()+24*60*60*1e3})}return expressBody(body)}}return next()};export{caching};